def run(ghosts: pd.DataFrame) -> list[Decision]:
    decisions: list[Decision] = []
    for _, l in ghosts.iterrows():
        if protection_reason(l) is not None:
            continue
        hashtag = "#vc-junk: ghost-unprotected-surplus"
        decisions.append(
            Decision(
                id=l["Id"], hash=l["Hash"], name=l["Name"],
                location=l.get("Owner", ""), guardian_class="",
                action="junk", tag="junk",
                note=append_tool_clause(l["Notes"], hashtag), kept_id="",
            )
        )
    return decisions
